"use strict";
(()=>{
 let data=null,activeMerchant=null,tab='handover',loading=null,lastLedger=null;
 const names={support:'找人一起解决困难',learning:'看看别家店的办法',handover:'打印清单、交接给别人',impact:'看看这30天有什么变化',industry:'分行业核查',mutual:'街坊互助'};
 const box=document.createElement('dialog');box.id='community-dialog';box.setAttribute('aria-labelledby','community-title');document.body.append(box);
 const paper=document.createElement('dialog');paper.id='community-print-dialog';paper.setAttribute('aria-labelledby','print-title');document.body.append(paper);
 const quick=document.createElement('aside');quick.id='quick-usage';quick.className='quick-usage';quick.hidden=true;quick.setAttribute('aria-label','随时继续操作');document.body.append(quick);
 const root=()=>'/api/merchants/'+encodeURIComponent(state.merchant.merchant_id);
 const dateNow=()=>{const d=new Date();return [d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-')};
 const cb=(text,action,extra='',primary=false)=>`<button type="button" class="button ${primary?'primary':'secondary'}" data-comm="${action}" ${extra}>${h(text)}</button>`;
 const field=(label,name,value='',type='text',extra='')=>`<label class="form-label">${h(label)}<input class="field" name="${name}" type="${type}" value="${h(value)}" ${extra}></label>`;
 const area=(label,name,value='',extra='required')=>`<label class="form-label">${h(label)}<textarea class="field" name="${name}" ${extra}>${h(value)}</textarea></label>`;
 const check=(label,name)=>`<label class="checkbox-line"><input type="checkbox" name="${name}" required>${h(label)}</label>`;
 const form=(kind,body,submit='核对并保存')=>`<form data-community-form="${kind}" class="comm-form">${body}<p class="form-error" role="alert" hidden></p><div class="comm-form-actions">${cb('返回工具页','tab',`data-tab="${tab}"`)}<button class="button primary" type="submit">${h(submit)}</button></div></form>`;
 const empty=(text)=>`<p class="comm-empty">${h(text)}</p>`;
 const currentAgenda=()=>data?.agendas?.agendas?.find(a=>a.current);
 function go(view,selector){if(box.open)box.close();setView(view);requestAnimationFrame(()=>{const el=document.querySelector(selector||'#view-'+view);if(el){const detail=el.closest('details');if(detail)detail.open=true;el.scrollIntoView({behavior:'smooth',block:'start'})}})}
 async function load(force=false){if(!state.merchant)return null;const id=state.merchant.merchant_id;if(!force&&data&&activeMerchant===id)return data;if(loading&&activeMerchant===id)return loading;activeMerchant=id;data=null;loading=api(root()+'/community').then(d=>{if(state.merchant?.merchant_id===id){data=d;renderGuide();if(box.open)renderHub();globalThis.RebirthApp?.contextChanged()}return d}).finally(()=>{loading=null});return loading}
 function renderGuide(){const guide=document.querySelector('#usage-guide');if(!guide)return;if(state.booting){guide.innerHTML='<p role="status">正在读取本机店铺与使用进度，请稍候…</p>';quick.hidden=true;return}const m=state.merchant,fresh=state.report?.result&&!state.report.ledger_changed&&!state.report.context_changed&&!['running','failed','cancelled','interrupted'].includes(state.report.status),a=currentAgenda();let label='第一步：添加我的店铺',action='create',why='先填写知道的现金、商品和问题；不确定的地方可以留待核实。';if(m){if(state.busy){label='查看正在进行的核查';action='analysis';why='进度按实际事件显示，核查期间不要重复提交。'}else if(a&&!a.stale&&fresh){label='下一步：查看我的行动日程';action='agenda';why='按日期逐项行动，记录实际情况；需要纸单时使用大字打印。'}else if(fresh){label='下一步：生成总结与日程';action='generate';why='只选一个方向，先预览每天做什么，再确认保存。'}else{label='下一步：进入经营分析';action='analysis';why='核对当前资料后再点击“开始经营核查”；行业专项也可从下方公益工具进入。'}}
 quick.innerHTML=cb(label,action,'',true)+cb('陪跑工具','hub');
 guide.innerHTML=`<div class="usage-main"><div><span class="comm-eyebrow">从这里开始 · 每一步都有去处</span><h2>${h(m?'现在，接着做哪一步？':'第一次使用，先从一间店开始。')}</h2><p>${h(why)}</p></div>${cb(label,action,'',true)}</div><div class="usage-steps" aria-label="使用步骤">${[['create','1','填写店铺资料','先记录事实'],['analysis','2','完成经营核查','看依据与待办'],['generate','3','生成行动日程','安排具体日期'],['agenda','4','记录行动与复盘','把结果留下']].map(([act,n,title,note],i)=>`<button type="button" data-comm="${act}" class="usage-step ${i===0&&m||i===1&&fresh||i>1&&a?'is-ready':''}"><span>${n}</span><div><strong>${title}</strong><small>${note}</small></div></button>`).join('')}</div><div class="usage-tools">${cb('查看使用指南','guide')}${cb('大字模式','large',`aria-pressed="${document.body.classList.contains('comm-large')}"`)}${cb('大字打印与陪跑工具','hub')}${cb(document.body.classList.contains('workbench-focused')?'展开店内场景':'收起店内场景','scene')}</div>`;
 }
 const base=renderExtras;renderExtras=function(){base();document.body.classList.toggle('workbench-focused',compact);let guide=document.querySelector('#usage-guide');if(!guide){guide=document.createElement('section');guide.id='usage-guide';guide.className='usage-guide';document.querySelector('.shop-switch')?.after(guide);new IntersectionObserver(entries=>{quick.hidden=entries[0].isIntersecting},{threshold:0}).observe(guide)}renderGuide();if(state.merchant?.merchant_id!==lastLedger){lastLedger=state.merchant?.merchant_id;if(box.open)box.close();load(true).catch(err=>toast('公益工具暂未加载：'+err.message))}const overview=document.querySelector('#view-overview');const hub=document.createElement('section');hub.className='community-entry';hub.innerHTML=`<span class="comm-eyebrow">把一次分析，接成持续的陪伴</span><h2>小店陪跑工具</h2><p>这些工具都在本机使用。选择一项，就能看到填写、保存和下一步入口。</p><div class="community-cards">${Object.entries(names).map(([key,name],i)=>`<button type="button" data-comm="tab" data-tab="${key}"><small>0${i+1}</small><strong>${name}</strong><span>${['一件困难，持续跟到店主回访','借鉴一步，把结果接回来','带走纸单，逐项交接','冻结基准，记录真实变化','按不同生意核对关键量','自愿登记，分别确认交接'][i]}</span><b aria-hidden="true">↗</b></button>`).join('')}</div>`;overview.querySelector('.hero')?.before(hub)};
 try{document.body.classList.toggle('comm-large',localStorage.getItem('rebirth_large_type')==='on')}catch{}
 function renderHub(){if(!data)return;box.innerHTML=`<div class="dialog-heading"><div><span class="eyebrow">${data.synthetic?'模拟案例 · 不计为真实受益':'本机店铺工具 · 不公开资料'}</span><h2 id="community-title">小店陪跑工具</h2><p>先选工具，再填写；保存后会显示记录和下一步。</p></div><button class="icon-button" type="button" data-comm="close" aria-label="关闭陪跑工具">×</button></div><nav class="comm-tabs" aria-label="选择陪跑工具">${Object.entries(names).map(([key,name])=>`<button type="button" data-comm="tab" data-tab="${key}" ${tab===key?'aria-current="page"':''}>${name}</button>`).join('')}</nav><div class="comm-body" id="community-content">${renderTab()}</div>`;globalThis.RebirthApp?.communityPage(tab);globalThis.RebirthSocial?.afterRender()}
 async function openHub(key=tab){if(state.booting)return;if(!state.merchant){toast('请先添加或选择店铺，再使用陪跑工具');openEditor(false);return}tab=key;if(!box.open){box.innerHTML=`<div class="comm-body"><h2 id="community-title">${h(names[key]||'小店陪跑')}</h2><p role="status">正在读取本机记录…</p></div>`;box.showModal()}try{await load(true)}catch(err){box.innerHTML=`<div class="comm-body"><h2 id="community-title">工具暂未加载</h2><p>${h(err.message)}</p>${cb('重新加载','reload')}${cb('关闭','close')}</div>`}}
 function renderTab(){if(tab==='support'||tab==='learning')return globalThis.RebirthSocial?.render(tab)||'<p>请刷新页面加载陪跑功能。</p>';if(tab==='handover'){const a=currentAgenda();return `<div class="comm-intro"><h3>把明天要做的事，带回店里。</h3><p>先预览大字行动单。有人协助整理时，再记录一次由店主核对的交接；不替店主确认原账。</p></div>${a?`<div class="comm-banner"><strong>当前日程：${h(a.days[0].date)} — ${h(a.days.at(-1).date)}</strong><p>${a.stale?'依据已有变化，先重新核查再生成当前日程。':'已有'+a.task_count+'项具体任务；打印与交接都引用这个版本。'}</p>${cb('预览大字行动单','print-agenda')}${cb('登记一次陪跑交接','handover-form',a.stale?'disabled':'',true)}${cb('回到行动日程','agenda')}</div>`:`<div class="comm-banner"><p>还没有行动日程。请先完成经营核查，再生成一份日程。</p>${cb('进入经营分析','analysis','',true)}</div>`}<h4>已保存的交接记录</h4>${data.handovers.slice().reverse().map(r=>`<article class="comm-record"><strong>${h(r.data.helper_alias)} · ${r.data.help_minutes}分钟</strong><p>下次核对 ${h(r.data.next_check_on)} · ${r.data.merchant_reviewed?'本次交接已逐项核对':''}</p><p>${h(r.data.notes)}</p>${cb('预览交接页','print-handover',`data-id="${h(r.id)}"`)}</article>`).join('')||empty('尚无交接记录。独立使用也可以直接打印行动单。')}`}
 if(tab==='impact')return `<div class="comm-intro"><h3>先留下起点，再回看真实的变化。</h3><p>每个档案固定一项指标与统计范围。基准保存后不改写；观察、暂停、没有改善都可以记录，前后变化不直接归因于本工具。</p>${cb('建立看看这30天有什么变化','impact-form','',true)}</div>${data.cases.slice().reverse().map(c=>`<article class="comm-record"><div class="comm-record-head"><h4>${h(c.data.metric_label)}</h4><span class="tag">${c.data.synthetic?'模拟案例':'店主记录'} · ${c.latest?{observed:'继续观察',paused:'暂停观察',stopped:'已停止尝试'}[c.latest.data.status]:'待首次观察'}</span></div><p>${h(c.data.goal)}<br>统计范围：${h(c.data.scope)}<br>建议30天回看日期：${h(c.review_on)} · ${c.latest?"最近观察距基准"+c.elapsed_days+"天":"尚未记录观察"}</p><div class="comm-metrics"><div>冻结基准<strong>${h(c.data.baseline_value)} ${h(c.data.unit)}</strong><small>${h(c.data.baseline_date)}</small></div><div>最新观察<strong>${c.latest?h(c.latest.data.value)+' '+h(c.data.unit):'尚未记录'}</strong><small>${c.latest?h(c.latest.data.observed_on):'可在同一口径下补记'}</small></div><div>观察值减基准<strong>${c.difference===null?'待观察':h(c.difference)+' '+h(c.data.unit)}</strong><small>不等同于系统造成的改善</small></div></div>${c.latest?`<p>实际行动：${h(c.latest.data.actions)}<br>外部影响：${h(c.latest.data.external_factors)}<br>累计额外投入：${h(c.latest.data.extra_spend)}元、${c.latest.data.extra_minutes}分钟</p>`:''}<div class="comm-actions">${cb('记录观察／暂停／更正','observe-form',`data-id="${h(c.id)}"`)}${cb('预览成效档案','print-impact',`data-id="${h(c.id)}"`)}</div><details><summary>查看基准来源与${c.history.length}次观察</summary><p>基准来源：${h(c.data.source_note)}</p>${c.history.map(o=>`<p>${h(o.data.observed_on)}：${h(o.data.value)} ${h(c.data.unit)} · ${h(o.data.source_note)} · ${h({observed:'继续观察',paused:'暂停观察',stopped:'已停止尝试'}[o.data.status])}</p>`).join('')}</details></article>`).join('')||empty('先选一个能核对的指标，记录基准值与来源。不会凭网站访问量推算受益人数。')}`;
 if(tab==='industry')return `<div class="comm-intro"><h3>不同的小店，先看对关键的量。</h3><p>选择生意类型，填写实际记录，得到专项计算、风险提示与三日准备行动单。此工具不改写原底账；</p><div class="industry-choices">${[['retail','社区零售','库存、周转与补货现金'],['food','餐饮小店','批次、损耗与实际用量'],['repair','便民修理','工时、排单与返工']].map(([k,n,d])=>`<button type="button" data-comm="industry-form" data-kind="${k}"><strong>${n}</strong><span>${d}</span></button>`).join('')}</div></div>${data.industry_checks.slice().reverse().map(r=>industryHtml(r)).join('')||empty('选择上方一类小店即可开始，未知数字允许留空。')}`;
 return mutualHtml();
 }
 function industryHtml(r){const d=r.data;return `<article class="comm-record"><h4>${h({retail:'社区零售',food:'餐饮',repair:'便民修理'}[d.industry])}专项核查 · ${h(d.observed_on)}</h4><div class="comm-metrics">${d.metrics.map(m=>`<div>${h(m.label)}<strong>${m.value===null?'待核实':h(m.value)+' '+h(m.unit)}</strong></div>`).join('')}</div>${d.warnings.map(w=>`<p class="note-box amber">${h(w)}</p>`).join('')}<details open><summary>三日准备行动</summary>${d.tasks.map(t=>`<p><strong>${h(t.date)} · ${h(t.title)}</strong><br>${h(t.steps)}<br>留下：${h(t.deliverable)} · 约${t.minutes}分钟，不新增经营投入</p>`).join('')}</details><p class="form-hint">${h(d.notice)} 来源：${h(d.source_note)}</p>${cb('大字预览／打印行动单','print-industry',`data-id="${h(r.id)}"`)}</article>`}
 function mutualHtml(){return `<div class="comm-intro"><h3>一间店的闲置，也许能帮上另一间店。</h3><p>仅在这台电脑的互助目录登记，不会发布公网或发送联系消息。提供方登记交接后，需切换接收店铺分别确认；真实与合成记录分开显示。</p>${cb('登记本店可共享资源','resource-form','',true)}</div><h4>本机互助目录 · ${data.synthetic?'模拟案例区':'实际登记区'}</h4>${data.resources.map(r=>`<article class="comm-record"><div class="comm-record-head"><h4>${h(r.data.title)}</h4><span class="tag">${r.owned?'本店提供':'其他店铺提供'} · ${r.data.status==='withdrawn'?'已撤回':r.remaining+' '+h(r.data.unit)+'未交接'}</span></div><p>${h(r.data.owner_alias)} · ${h(r.data.area)}<br>条件：${h(r.data.condition)}<br>可用期 ${h(r.data.available_from)} — ${h(r.data.available_until)}</p><div class="comm-actions">${r.owned&&r.data.status==='available'?cb('登记交接给另一家店','transfer-form',`data-id="${h(r.data.listing_id)}" ${r.pending||r.remaining<1?'disabled':''}`)+cb('修改资源单','resource-form',`data-id="${h(r.data.listing_id)}" ${r.pending?'disabled':''}`)+cb('撤回资源单','withdraw',`data-id="${h(r.data.listing_id)}" ${r.pending?'disabled':''}`):''}</div>${r.pending?'<p class="form-hint">已有待确认交接，处理后才能继续安排或修改。</p>':''}</article>`).join('')||empty('没有登记资源。使用上方“登记本店可共享资源”添加一条。')}<h4>与本店有关的交接</h4>${data.transfers.slice().reverse().map(t=>`<article class="comm-record"><strong>${h(t.data.title)} · ${t.data.quantity} ${h(t.data.unit)}</strong><p>日期 ${h(t.data.occurred_on)} · 本店为${t.role==='owner'?'提供方':'接收方'} · ${h({pending:'待接收店确认',confirmed:'双方分别登记确认',declined:'接收方拒绝',cancelled:'提供方取消'}[t.status])}</p><p>提供方依据：${h(t.data.source_note)}</p>${t.receipt?`<p>接收／处理依据：${h(t.receipt.data.source_note)}</p>`:''}<div class="comm-actions">${t.status==='pending'?(t.role==='recipient'?cb('核对并确认／拒绝','receipt-form',`data-id="${h(t.id)}"`,true):cb('取消这次待确认交接','cancel-form',`data-id="${h(t.id)}"`)+cb('切换到接收店铺核对','switch-recipient',`data-recipient="${h(t.data.recipient)}"`)):''}</div><p class="form-hint">本机分别登记，不代表线上身份认证或独立实地核验。</p></article>`).join('')||empty('尚无交接。双方确认前不会计作已交接数量。')}`}

 function showForm(kind,id,industry){let body='';const a=currentAgenda();
  if(kind==='handover'){
   if(!a||a.stale){toast('先生成当前有效的行动日程');return}
   body=`<h3>登记一次由店主核对的交接</h3><div class="form-grid two"><label class="form-label">谁在记录<select class="field" name="operator_role"><option value="merchant">店主本人</option><option value="companion">协助记录者</option></select></label>${field('记录者称呼（不必填全名）','helper_alias','','text','required maxlength="80"')}${field('本次协助用时（分钟）','help_minutes','15','number','required min="0" max="1440"')}${field('下次核对日期','next_check_on',dateNow(),'date','required')}</div>${area('交接了什么、店主接下来做什么','notes')}${check('已与店主逐项核对本次交接内容；这不替代原账确认','merchant_reviewed')}<input type="hidden" name="agenda_id" value="${h(a.id)}">`;
  }else if(kind==='impact')body=`<h3>冻结一个能核对的起点</h3><p class="note-box">同一档案固定一个指标、单位与统计范围。保存后保留基准，不能看到结果后改口径。</p><label class="form-label">要跟踪的指标<select class="field" name="metric">${Object.entries(data.metric_definitions).map(([k,v])=>`<option value="${k}">${h(v[0])}（${h(v[1])}）</option>`).join('')}</select></label>${area('固定统计范围与方法（如指定三类商品、同一盘点口径）','scope')}${area('希望解决什么问题','goal')}<div class="form-grid two">${field('基准日期','baseline_date',dateNow(),'date','required')}${field('基准值（按所选单位，未知请先核实）','baseline_value','','number','required min="0" step="0.01"')}</div>${area('基准来自哪份记录','source_note')}${check('已核对基准与统计口径，理解保存后不会改写原基准','confirmed')}`;
  else if(kind==='observe'){const c=data.cases.find(c=>c.id===id);body=`<h3>记录观察，也允许暂停或没有改善</h3><p class="note-box">固定口径：${h(c.data.scope)}<br>${h(c.data.metric_label)} · 基准 ${h(c.data.baseline_value)} ${h(c.data.unit)}，不能修改单位。</p><input type="hidden" name="case_id" value="${h(id)}"><input type="hidden" name="previous_id" value="${h(c.latest?.id||'')}"><div class="form-grid two">${field('观察截至日期','observed_on',dateNow(),'date',`required min="${h(c.data.baseline_date)}"`)}${field('同一口径的观察值（'+c.data.unit+'）','value','','number','required min="0" step="0.01"')}${field('累计额外支出（元）','extra_spend','','number','required min="0" step="0.01"')}${field('累计额外用时（分钟）','extra_minutes','','number','required min="0" step="1"')}</div><label class="form-label">目前状态<select class="field" name="status"><option value="observed">继续观察</option><option value="paused">暂停</option><option value="stopped">停止这次尝试</option></select></label>${area('实际做了什么，或为什么没有做','actions')}${area('同期的天气、客流、季节、其他改变等影响（不知道可写尚不清楚）','external_factors')}${area('观察或更正来自哪份记录','source_note')}${check('确认与基准使用同一范围、单位和统计方法','same_scope_confirmed')}`}
  else if(kind==='industry'){body=`<h3>${h({retail:'社区零售',food:'餐饮小店',repair:'便民修理'}[industry])}专项核查</h3><p class="note-box">填写实际记录，未知可以留空。输出的是本地规则计算与准备行动，不自动批准投入，也不替代专业现场判断。</p><p class="form-hint">${h({retail:'本次只核对一种商品或同一计价单元，数量、成本与售价须对应同一范围，不把不同单价混算。',food:'只核对同一批次和单位：盘点总量指此刻实物总量，包含待剔除的损耗；已经消耗的原料不重复计入。订单与每单贡献也须采用同一范围。',repair:'只核对同类服务；按代表性实测工时粗算容量，待料、休息和不同订单的差异仍须逐单核对。'}[industry])}</p><input type="hidden" name="industry" value="${h(industry)}">${field('记录截至日期','observed_on',dateNow(),'date','required')}<div class="form-grid two">${data.industry_fields[industry].map(([key,label,unit])=>field(label+'（'+unit+'）',key,'','number',`step="${['batch','waste','daily_use','unit_cost','price','cash','reserve','due','margin','fixed','material'].includes(key)?'0.01':'1'}" ${key==='margin'?'':'min="0"'}`)).join('')}</div>${area('这些数据依据什么填写','source_note')}`}
  else if(kind==='resource'){const old=id?data.resources.find(r=>r.data.listing_id===id):null,d=old?.data||{};body=`<h3>${old?'修改本店资源单':'登记本店可共享资源'}</h3><p class="note-box">只填写可共享内容、粗略区域和使用条件。不要填写客户资料、账户、电话或家庭详细地址；本机登记不等于已发布公网。</p>${old?`<input type="hidden" name="listing_id" value="${h(d.listing_id)}"><input type="hidden" name="expected_record_id" value="${h(old.record_id)}">`:''}<div class="form-grid two">${field('资源或技能名称','title',d.title||'','text','required maxlength="160"')}${field('店铺对外称呼','owner_alias',d.owner_alias||'','text','required maxlength="80"')}${field('登记总量（已交接量仍包含在内）','quantity',d.quantity||1,'number','required min="1" max="1000000" step="1"')}${field('单位（台／件／批／小时等）','unit',d.unit||'件','text','required maxlength="20"')}${field('可用开始日','available_from',d.available_from||dateNow(),'date','required')}${field('可用截止日','available_until',d.available_until||dateNow(),'date','required')}${field('粗略区域（如某街区）','area',d.area||'','text','required maxlength="120"')}</div>${area('状态、用途、交接条件和需核对事项','condition',d.condition||'')}${area('这份登记的来源或修改原因','source_note',d.source_note||'')}${check('同意这份登记在本机互助目录显示，未授权公开其他经营资料','directory_consent')}`}
  else if(kind==='transfer'){const r=data.resources.find(r=>r.data.listing_id===id),options=state.merchants.filter(m=>m.merchant_id!==state.merchant.merchant_id&&m.synthetic===state.merchant.synthetic);if(!options.length){document.querySelector('#community-content').innerHTML=`<h3>先准备接收店铺档案</h3><p>目前没有另一家同类型的本机店铺。先添加接收店铺，分别登记；不要把模拟案例单交给真实店铺确认。</p>${cb('添加接收店铺','new-recipient','',true)}${cb('返回互助目录','tab','data-tab="mutual"')}`;return}body=`<h3>提供方登记一次交接</h3><p>${h(r.data.title)} · 未交接余量 ${r.remaining} ${h(r.data.unit)}</p><input type="hidden" name="listing_id" value="${h(id)}"><label class="form-label">接收店铺<select class="field" name="recipient">${options.map(m=>`<option value="${h(m.merchant_id)}">${h(m.name)}${state.merchants.filter(x=>x.name===m.name).length>1?" · "+h(m.merchant_id.slice(-6)):""}</option>`).join('')}</select></label><div class="form-grid two">${field('交接数量','quantity','1','number',`required min="1" max="${r.remaining}" step="1"`)}${field('实际交接日期','occurred_on',dateNow(),'date','required')}</div>${area('提供方核对的交接依据','source_note')}${check('提供方已核对这笔登记，接收方仍须切换店铺分别确认','owner_confirmed')}`}
  else if(kind==='receipt'||kind==='cancel'){const t=data.transfers.find(t=>t.id===id);body=`<h3>${kind==='cancel'?'取消待确认交接':'接收方核对交接'}</h3><p>${h(t.data.title)} · ${t.data.quantity} ${h(t.data.unit)} · ${h(t.data.occurred_on)}</p><input type="hidden" name="transfer_id" value="${h(id)}">${kind==='cancel'?'<input type="hidden" name="decision" value="cancelled">':'<label class="form-label">实际结果<select class="field" name="decision"><option value="confirmed">已核对收到上述数量</option><option value="declined">未收到／不同意这笔交接</option></select></label>'}${area('核对或取消依据（写清记录来源）','source_note')}${check('已核对本次结果；本机登记不等同于身份认证或实地核验','confirmed')}`}
  document.querySelector('#community-content').innerHTML=form(kind,body,kind==='industry'?'生成核查与三日行动单':'核对并保存');document.querySelector('#community-content').scrollTop=0;globalThis.RebirthApp?.communityForm(kind);
 }
 const printStyle='body{font-family:"Microsoft YaHei",sans-serif;color:#263d32;margin:25px;font-size:20px;line-height:1.9}h1{font-size:30px}h2{font-size:25px}h3{font-size:23px}small{font-size:15px}article{border-bottom:1px solid #a9b59a;padding:18px 0;break-inside:avoid}li{padding:5px 0}.paper-note{border:1px solid #9fac90;padding:15px}blockquote{margin:10px 0;padding-left:15px;border-left:2px solid #8f9f7a}@page{size:A4;margin:18mm}@media print{body{margin:0}}';
 let printContent='',printTitle='';
 function previewPrint(title,html){globalThis.RebirthApp?.preparePrint();if(box.open)box.close();printContent=html;printTitle=title;paper.innerHTML=`<div class="print-controls"><h2 id="print-title">${h(title)}</h2><p>这是大字打印预览。默认不展示余额和客户资料，交给他人前请检查文字。</p><div>${cb('打印／另存PDF','print')}${cb('下载可打印网页','download-paper')}${cb('返回陪跑工具','back-hub')}</div></div><article id="community-print-sheet">${html}</article>`;paper.showModal();globalThis.RebirthApp?.printPage()}
 function agendaPaper(a){const redact=s=>String(s).replace(/¥\s*[\d,.]+/g,'金额见店主原账');return `<h1>小店大字行动单</h1><p>${h(a.days[0].date)} 至 ${h(a.days.at(-1).date)} · ${a.synthetic?'模拟案例':'店主记录'}</p>${a.stale?'<p class="paper-note">依据已变化：仅供历史回查，请重新核查后执行。</p>':''}<p>${h(a.scope)} · 当前仅记录任务，不替店主执行或证明经营效果。</p>${a.days.filter(d=>d.tasks.length).map(d=>`<section><h2>${h(d.date)} · 约${d.minutes}分钟</h2>${d.tasks.map(t=>`<article><h3>□ ${h(t.title)}</h3><p>${h({pending:'待做',done:'已记完成',skipped:'已记暂停'}[t.status])} · 约${t.minutes}分钟</p><ol>${t.steps.map(s=>`<li>${h(redact(s))}</li>`).join('')}</ol><p><strong>完成标准：</strong>${h(redact(t.deliverable))}</p>${t.depends_on?.length?`<p><strong>先完成：</strong>${h(t.depends_on.map(id=>a.days.flatMap(d=>d.tasks).find(x=>x.id===id)?.title||id).join('、'))}</p>`:''}<p><strong>暂停条件：</strong>${h(redact(t.stop_when))}</p><p>记录／日期：________________________</p></article>`).join('')}</section>`).join('')}<p class="paper-note">先完成前置任务，条件变化时暂停。金额以店主原账为准；勾选只是自报进度，不能当作收益或社会成效证明。</p>`}
 function printImpact(c){const d=c.data,o=c.latest?.data;previewPrint('30天陪跑成效档案',`<h1>一间小店的30天陪跑档案</h1><p>${d.synthetic?'模拟案例，不能作为真实社会成效':'店主本机记录，未经独立核验'}</p><h2>起点</h2><p>${h(d.goal)}<br>固定范围：${h(d.scope)}<br>${h(d.baseline_date)}：${h(d.metric_label)} ${h(d.baseline_value)} ${h(d.unit)}<br>基准来源：${h(d.source_note)}</p><p>建议30天回看日期：${h(c.review_on)}</p><h2>实际行动与观察</h2>${o?`<p>${h(o.observed_on)}：${h(o.value)} ${h(d.unit)} · ${h({observed:'继续观察',paused:'暂停观察',stopped:'已停止尝试'}[o.status])}<br>实际做了：${h(o.actions)}<br>外部影响：${h(o.external_factors)}<br>累计额外投入：${h(o.extra_spend)}元、${o.extra_minutes}分钟<br>观察来源：${h(o.source_note)}</p>`:'<p>尚未记录观察，不补造变化。</p>'}<h2>回看</h2><p>观察值减基准：${c.difference===null?'待观察':h(c.difference)+' '+h(d.unit)}。${c.elapsed_days<30?'尚未完成30天观察。':'已达到30天观察时长。'}前后差异不自动归因于本工具，暂停、未改善与成本同样保留。</p>`)}
 document.addEventListener('submit',async e=>{const form=e.target.closest('[data-community-form]');if(!form)return;e.preventDefault();const button=form.querySelector('[type=submit]'),error=form.querySelector('.form-error'),kind=form.dataset.communityForm,f=new FormData(form),payload=Object.fromEntries(f.entries());button.disabled=true;error.hidden=true;try{for(const k of ['merchant_reviewed','confirmed','same_scope_confirmed','directory_consent','owner_confirmed'])if(f.has(k))payload[k]=true;for(const k of ['help_minutes','extra_minutes','quantity'])if(f.has(k))payload[k]=intText(f.get(k));if(f.has('previous_id'))payload.previous_id=f.get('previous_id')||null;
  if(kind==='industry'){payload.values={};for(const [k] of data.industry_fields[payload.industry]){payload.values[k]=f.get(k)||null;delete payload[k]}}
  const routes={handover:'support-handover',impact:'impact-start',observe:'impact-observe',industry:'industry-review',resource:'mutual-resource',transfer:'mutual-transfer',receipt:'mutual-receipt',cancel:'mutual-receipt'};await api(root()+'/'+routes[kind],payload);toast(kind==='industry'?'专项核查和三日行动单已保存':'记录已保存在本机');await load(true)
 }catch(err){error.textContent=err.message;error.hidden=false;error.scrollIntoView({block:'nearest'})}finally{button.disabled=false}});
 document.addEventListener('click',async e=>{const b=e.target.closest('[data-comm]');if(!b)return;const action=b.dataset.comm;try{
  if(action==='close'){box.close();return}
  if(action==='large'){document.body.classList.toggle('comm-large');try{localStorage.setItem('rebirth_large_type',document.body.classList.contains('comm-large')?'on':'off')}catch{}renderGuide();return}
  if(action==='scene'){compact=!compact;document.body.classList.toggle('workbench-focused',compact);renderGuide();return}
  if(action==='guide'){box.innerHTML=`<div class="dialog-heading"><h2 id="community-title">按这四步使用</h2><button class="icon-button" data-comm="close" aria-label="关闭使用指南">×</button></div><div class="comm-body"><ol class="how-to-list"><li><strong>填写店铺资料</strong><p>新增店铺，填现金、商品和必要付款。未知留空，有表格时可导入；先用合成示例熟悉也可以。</p>${cb('去填写资料','create')}</li><li><strong>完成经营核查</strong><p>进入经营分析，点击“开始经营核查”。看清待核对项；资料修改后要重新核查。</p>${cb('去经营分析','analysis')}</li><li><strong>生成总结与日程</strong><p>分析完成后点击“生成总结与行动日程”。选择起始日、时间和一个方向，预览后保存。</p>${cb('去生成行动日程','generate')}</li><li><strong>按日行动，留下实际反馈</strong><p>行动与复盘里查看日程、记录进度。纸单、陪跑交接、成效档案和互助都可从常驻公益工具进入。</p>${cb('查看我的日程','agenda')}${cb('打开陪跑工具','hub')}</li></ol></div>`;if(!box.open)box.showModal();return}
  if(action==='create'||action==='new-recipient'){if(box.open)box.close();openEditor(action==='create'&&!!state.merchant);return}
  if(action==='analysis'){go('analysis');return}
  if(action==='agenda'){if(!state.merchant){openEditor(false);return}go('feedback','#agenda-board');return}
  if(action==='generate'){if(box.open)box.close();setView('analysis');const button=document.querySelector('#agenda-entry [data-agenda-action="start"]');if(!button||button.disabled){toast('请先在经营分析里完成当前资料的本地核查');go('analysis');return}button.click();return}
  if(action==='hub'||action==='tab'||action==='reload'){if(action==='reload')data=null;await openHub(b.dataset.tab||tab);return}
  if(action.endsWith('-form')){showForm(action.replace('-form',''),b.dataset.id,b.dataset.kind);return}
  if(action==='switch-recipient'){box.close();await selectMerchant(b.dataset.recipient);data=null;await openHub('mutual');toast('已切换接收店铺，请根据实际交接独立确认');return}
  if(action==='withdraw'){const r=data.resources.find(r=>r.data.listing_id===b.dataset.id);b.disabled=true;await api(root()+'/mutual-resource',{...r.data,status:'withdrawn',expected_record_id:r.record_id,directory_consent:true});await load(true);return}
  if(action==='print-agenda'){const a=currentAgenda();if(!a){toast('先生成行动日程');return}previewPrint('大字行动单',agendaPaper(a));return}
  if(action==='print-handover'){const r=data.handovers.find(r=>r.id===b.dataset.id),d=r.data;previewPrint('公益陪跑交接页',`<h1>小店陪跑交接页</h1><p>${d.synthetic?'模拟案例，不是真实受益证明':'店主本机记录'}</p><p>记录者：${h(d.helper_alias)} · 本次协助 ${d.help_minutes}分钟<br>下次核对：${h(d.next_check_on)}<br>本次交接已由店主逐项核对；不替代原账确认。</p><h2>这次交接了什么</h2><p>${h(d.notes)}</p><h2>交接当时的行动快照</h2><p class="paper-note">这是留档的交接版本，纸单不会自动更新。执行前请回到当前行动日程核对资料、日期与前置条件。</p>${agendaPaper(d.agenda_snapshot)}<p>${h(d.notice)}</p>`);return}
  if(action==='print-impact'){printImpact(data.cases.find(c=>c.id===b.dataset.id));return}
  if(action==='print-industry'){const d=data.industry_checks.find(r=>r.id===b.dataset.id).data;previewPrint('分行业三日准备行动单',`<h1>${h({retail:'社区零售',food:'餐饮',repair:'便民修理'}[d.industry])}三日准备行动单</h1><p>${d.synthetic?'模拟案例':'店主记录'} · 截至${h(d.observed_on)}<br>来源：${h(d.source_note)}</p>${d.warnings.map(w=>`<p class="paper-note">${h(w)}</p>`).join('')}${d.tasks.map(t=>`<article><h2>□ ${h(t.date)} · ${h(t.title)}</h2><p>${h(t.steps)}</p><p>完成标准：${h(t.deliverable)} · 约${t.minutes}分钟，不新增经营投入</p><p>实际记录：___________________</p></article>`).join('')}<p>${h(d.notice)}</p>`);return}
  if(action==='print'){window.print();return}
  if(action==='download-paper'){const content='<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'+h(printTitle)+'</title><style>'+printStyle+'</style><body>'+printContent+'</body></html>',url=URL.createObjectURL(new Blob([content],{type:'text/html;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download=printTitle+'-'+dateNow()+'.html';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);return}
  if(action==='back-hub'){paper.close();await openHub(tab);return}
 }catch(err){toast(err.message);b.disabled=false}});
 globalThis.RebirthCommunity={paper:previewPrint,open:openHub,form:showForm,data:()=>data,tab:()=>tab,refresh:()=>load(true),surface:(html,kind)=>{document.querySelector('#community-content').innerHTML=html;globalThis.RebirthApp?.communityForm(kind)}};
 document.addEventListener('rebirth-ready',renderGuide);
 let compact=true;
})();
